// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/databases", wrapper.ListDatabases)
	router.POST(options.BaseURL+"/databases", wrapper.CreateDatabase)
	router.DELETE(options.BaseURL+"/databases/:databaseId", wrapper.DeleteDatabase)
	router.GET(options.BaseURL+"/databases/:databaseId", wrapper.GetDatabase)
	router.PUT(options.BaseURL+"/databases/:databaseId", wrapper.UpdateDatabase)
	router.POST(options.BaseURL+"/databases/:databaseId/copy", wrapper.CopyDatabase)
	router.POST(options.BaseURL+"/databases/:databaseId/test", wrapper.TestDatabase)
	router.POST(options.BaseURL+"/database-tests", wrapper.TestDatabaseSettings)
	router.POST(options.BaseURL+"/limited-user-checks", wrapper.CheckLimitedUser)
	router.POST(options.BaseURL+"/limited-users", wrapper.CreateLimitedUser)
}

