// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// TestDatabaseSettings Test the connection with settings that are not saved
	// (POST /database-tests)
	TestDatabaseSettings(ctx context.Context, request TestDatabaseSettingsRequestObject) (TestDatabaseSettingsResponseObject, error)
	// ListDatabases List the databases of a workspace
	// (GET /databases)
	ListDatabases(ctx context.Context, request ListDatabasesRequestObject) (ListDatabasesResponseObject, error)
	// CreateDatabase Create a database in a workspace
	// (POST /databases)
	CreateDatabase(ctx context.Context, request CreateDatabaseRequestObject) (CreateDatabaseResponseObject, error)
	// DeleteDatabase Delete a database with its backups
	// (DELETE /databases/{databaseId})
	DeleteDatabase(ctx context.Context, request DeleteDatabaseRequestObject) (DeleteDatabaseResponseObject, error)
	// GetDatabase Get a database without its secrets
	// (GET /databases/{databaseId})
	GetDatabase(ctx context.Context, request GetDatabaseRequestObject) (GetDatabaseResponseObject, error)
	// UpdateDatabase Replace the name, the settings and the notifiers of a database
	// (PUT /databases/{databaseId})
	UpdateDatabase(ctx context.Context, request UpdateDatabaseRequestObject) (UpdateDatabaseResponseObject, error)
	// CopyDatabase Copy a database within its workspace
	// (POST /databases/{databaseId}/copy)
	CopyDatabase(ctx context.Context, request CopyDatabaseRequestObject) (CopyDatabaseResponseObject, error)
	// TestDatabase Test the connection of a saved database
	// (POST /databases/{databaseId}/test)
	TestDatabase(ctx context.Context, request TestDatabaseRequestObject) (TestDatabaseResponseObject, error)
	// CheckLimitedUser Check whether the connecting user may do more than a backup needs
	// (POST /limited-user-checks)
	CheckLimitedUser(ctx context.Context, request CheckLimitedUserRequestObject) (CheckLimitedUserResponseObject, error)
	// CreateLimitedUser Create a limited user on the database's server
	// (POST /limited-users)
	CreateLimitedUser(ctx context.Context, request CreateLimitedUserRequestObject) (CreateLimitedUserResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictGinServerOptions
}

// TestDatabaseSettings operation middleware
func (sh *strictHandler) TestDatabaseSettings(ctx *gin.Context) {
	var request TestDatabaseSettingsRequestObject

	var body TestDatabaseSettingsJSONRequestBody
	if err := ctx.ShouldBindJSON(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(ctx, err)
		return
	}
	request.Body = &body

	handler := func(ctx *gin.Context, request interface{}) (interface{}, error) {
		return sh.ssi.TestDatabaseSettings(ctx, request.(TestDatabaseSettingsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "TestDatabaseSettings")
	}

	response, err := handler(ctx, request)

	if err != nil {
		sh.options.HandlerErrorFunc(ctx, err)
	} else if validResponse, ok := response.(TestDatabaseSettingsResponseObject); ok {
		if err := validResponse.VisitTestDatabaseSettingsResponse(ctx.Writer); err != nil {
			sh.options.ResponseErrorHandlerFunc(ctx, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(ctx, fmt.Errorf("unexpected response type: %T", response))
	}
}

